- How would zero-weight edges affect the approach? 
- How to extend to count modulo a large prime or handle multiple sources?

## Why This Is Asked
Tests the ability to combine hash tables with heaps for real-time top-K queries under sliding-window expirations. It evaluates understanding of lazy cleanup techniques, time-based eviction strategies, and maintaining data consistency under concurrent updates.

## Key Concepts
- Hash map for O(1) task lookups and metadata storage
- Max-heap for efficient top-K ordering
- Lazy deletion to avoid expensive per-update heap removals
- Time-based expiration using timestamp validation

## Code Example
```javascript
class Leaderboard {
  constructor(W) {
    this.W = W;
    this.map = new Map(); // task_id -> {score, timestamp}
    this.heap = new MaxHeap(); // (score, task_id)
  }

  update(task_id, delta, ts) {
    const current = this.map.get(task_id) || { score: 0, timestamp: 0 };
    const updated = { 
      score: current.score + delta, 
      timestamp: ts 
    };
    this.map.set(task_id, updated);
    this.heap.push([updated.score, task_id]);
  }

  getTopK(k, current_ts) {
    const result = [];
    const temp = [];

    while (result.length < k && !this.heap.isEmpty()) {
      const [score, task_id] = this.heap.pop();
      const task = this.map.get(task_id);

      if (task && task.score === score && current_ts - task.timestamp <= this.W) {
        result.push({ task_id, score });
      } else {
        temp.push([score, task_id]);
      }
    }

    // Restore invalid entries
    temp.forEach(entry => this.heap.push(entry));

    return result;
  }
}
```

## Complexity Analysis
- **Update**: O(1) hash map + O(log n) heap push = O(log n)
- **Top-K query**: O(k log n) worst case due to lazy deletion
- **Space**: O(n) for hash map + heap (potentially O(n + m) where m are stale entries)
- **Expiration**: Handled during queries via timestamp validation

## Why This Is Asked

This question evaluates understanding of the Trie (prefix tree) data structure, covering insert, delete, and prefix-query operations with proper edge case handling.

## Key Concepts

- **Trie node structure**: Each node stores 26 child pointers, an end-of-word flag, and a pass-through counter for efficient prefix queries
- **Safe deletion**: Decrement counts along the path and only unmark end-of-word when the word actually exists
- **Prefix query**: Return the count at the prefix's last node in O(length of prefix) time
- **Duplicate handling**: Adding the same word twice increments the counter twice; deleting decrements twice, effectively removing one occurrence

## Code Example

```javascript
class TrieNode {
  constructor() {
    this.children = new Array(26).fill(null);
    this.isEndOfWord = false;
    this.count = 0;
  }
}

class Trie {
  constructor() {
    this.root = new TrieNode();
  }

  add(word) {
    let node = this.root;
    for (const char of word) {
      const index = char.charCodeAt(0) - 97;
      if (!node.children[index]) {
        node.children[index] = new TrieNode();
      }
      node = node.children[index];
      node.count++;
    }
    node.isEndOfWord = true;
  }

  delete(word) {
    let node = this.root;
    for (const char of word) {
      const index = char.charCodeAt(0) - 97;
      if (!node.children[index]) return;
      node = node.children[index];
      node.count--;
    }
    node.isEndOfWord = false;
  }

  countPrefix(prefix) {
    let node = this.root;
    for (const char of prefix) {
      const index = char.charCodeAt(0) - 97;
      if (!node.children[index]) return 0;
      node = node.children[index];
    }
    return node.count;
  }
}
```

## Why This Is Asked

Tests practical algorithm design that blends classic sorts and data-structure choices. It assesses the ability to identify run structures, select appropriate sorting strategies by run size, and implement an efficient, stable k-way merge.

## Key Concepts

- Natural monotone runs detection in O(n)
- Insertion sort for small ranges; mergesort for larger ranges
- K-way merge with a min-heap and lazy advancement
- Stability guarantees and complexity trade-offs

## Code Example

```javascript
function hybridSort(a){
  const n=a.length; 
  // 1) detect monotone runs
  const runs=[]; let i=0;
  while(i<n){
    let j=i+1;
    while(j<n && a[j-1] <= a[j]) j++;
    runs.push([i,j]);
    i=j;
  }
  // 2) sort each run
  for(const [l,r] of runs){
    if(r-l <= 32) insertionSort(a,l,r);
    else mergeSort(a,l,r);
  }
  // 3) k-way merge using a min-heap
  const heap=new MinHeap((x,y)=> x.val<y.val);
  for(let idx=0; idx<runs.length; idx++){
    const [l,r]=runs[idx];
    if(l<r) heap.push({val:a[l], pos:l, runIdx:idx});
  }
  const out=new Array(n); let k=0;
  while(!heap.isEmpty()){
    const {val,pos,runIdx}=heap.pop();
    out[k++]=val;
    const [l,r]=runs[runIdx];
    const next=pos+1;
    if(next<r) heap.push({val:a[next], pos:next, runIdx});
  }
  for(let t=0;t<n;t++) a[t]=out[t];
}

function insertionSort(a,l,r){
  for(let i=l+1;i<r;i++){
    const key=a[i]; let j=i-1;
    while(j>=l && a[j]>key){ a[j+1]=a[j]; j--; }
    a[j+1]=key;
  }
}

function mergeSort(a,l,r){
  if(r-l<=1) return;
  const m=(l+r)>>1;
  mergeSort(a,l,m); mergeSort(a,m,r);
  // merge [l,m) and [m,r)
  const left=a.slice(l,m); let i=0, j=m, t=l;
  while(i<left.length && j<r) a[t++]= left[i++]<a[j]? left[i-1]: a[j++];
  while(i<left.length) a[t++]=left[i++];
  while(j<r) a[t++]=a[j++];
}

class MinHeap{
  constructor(cmp){ this.a=[]; this.cmp=cmp||((x,y)=> x<y); }
  push(x){ this.a.push(x); this.bubbleUp(this.a.length-1); }
  pop(){ if(this.a.length===0) return null; const top=this.a[0]; const end=this.a.pop(); if(this.a.length){ this.a[0]=end; this.sinkDown(0); } return top; }
  isEmpty(){ return this.a.length===0; }
  bubbleUp(n){ const a=this.a[n]; while(n>0){ const p=(n-1)>>1; if(this.cmp(a, this.a[p])){ this.a[n]=this.a[p]; n=p; } else break; } this.a[n]=a; }
  sinkDown(n){ const length=this.a.length; const element=this.a[n]; while(true){ let child2=(n+1)*2, child1=child2-1; let swap=null; if(child1<length){ if(this.cmp(this.a[child1], element)) swap=child1; } if(child2<length){ if(this.cmp(this.a[child2], swap===null?element:this.a[child1])) swap=child2; } if(swap===null) break; this.a[n]=this.a[swap]; n=swap; } this.a[n]=element; }
}
```

